<script setup>
import {ref,computed,watch} from 'vue'
import MetricTrend from './MetricTrend.vue'
const props=defineProps({subject:String,subjects:Object,domain:Object})
const fresh=()=>({start:props.domain.scenario.meta.date,end:props.domain.scenario.meta.date,category:'all',entity:'all',unit:'all',shift:'all',status:'all',search:''})
const periods=[['today','当日'],['yesterday','昨日'],['this-week','本周'],['last-week','上周'],['this-month','本月'],['last-month','上月'],['this-year','今年'],['last-year','去年']]
function period(key){const r=props.domain.dateRange(key);f.value.start=r.start;f.value.end=r.end}
const f=ref(fresh()),selected=ref(null),detail=ref(false),drill=ref('all'),page=ref(1)
const labels=computed(()=>({nursing:['岗位角色','具体护士'],room:['手术间类别','手术间'],pacu:['复苏室','床位'],equipment:['设备类型','设备实例'],supply:['器械包类型','器械包']}[props.subject]||['范围','主体']))
const all=computed(()=>props.subjects.entities(props.subject))
const options=values=>[{value:'all',title:'全部'},...values.map(v=>({value:v,title:v}))]
const categories=computed(()=>options([...new Set(all.value.filter(e=>f.value.unit==='all'||e.unit===f.value.unit).map(e=>e.category))]))
const entities=computed(()=>all.value.filter(e=>(f.value.category==='all'||e.category===f.value.category)&&(f.value.unit==='all'||e.unit===f.value.unit)))
watch(()=>[f.value.category,f.value.unit],()=>{f.value.entity='all'})
watch(()=>f.value.unit,()=>{f.value.category='all'})
const rows=computed(()=>props.subjects.definitions(props.subject).map(d=>({...d,...props.subjects.value(d.id,f.value)})).filter(d=>d.name.includes(f.value.search||'')&&(f.value.status==='all'||d.status===f.value.status)))
const statuses={normal:'正常',warning:'预警',danger:'异常',unsupported:'不适用 / 无数据'},colors={normal:'success',warning:'warning',danger:'error',unsupported:'secondary'}
function open(m){selected.value=m;drill.value='all';page.value=1;detail.value=true}
const dates=computed(()=>{const end=[f.value.end,props.domain.scenario.meta.date].sort()[0];if(!end)return [];return Array.from({length:30},(_,i)=>{const d=new Date(end+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-29+i);return d.toISOString().slice(0,10)})})
const values=computed(()=>selected.value?dates.value.map(date=>props.subjects.value(selected.value.id,{...f.value,start:date,end:date,entity:drill.value==='all'?f.value.entity:drill.value}).value):[])
const breakdown=computed(()=>selected.value?props.subjects.selection(props.subject,f.value).map(e=>({...e,...props.subjects.value(selected.value.id,{...f.value,entity:e.id})})):[])
</script>
<template><section><VCard class="mb-6"><div class="toolbar"><strong>{{subjects.subjects[subject].name}} · 统计范围</strong><VBtn variant="text" @click="f=fresh()">重置筛选</VBtn></div><div class="d-flex flex-wrap px-6 pb-4" style="gap:8px"><VBtn v-for="[key,title] in periods" :key="key" size="small" variant="tonal" @click="period(key)">{{title}}</VBtn></div><div class="filters"><div class="filter-field"><label>开始日期</label><VTextField v-model="f.start" type="date" :max="f.end"/></div><div class="filter-field"><label>结束日期</label><VTextField v-model="f.end" type="date" :min="f.start" :max="domain.scenario.meta.date"/></div><template v-if="subject!=='hospital'"><div v-if="subject==='nursing'" class="filter-field"><label>护理单元</label><VSelect v-model="f.unit" :items="options([...new Set(all.map(e=>e.unit))])"/></div><div class="filter-field"><label>{{labels[0]}}</label><VSelect v-model="f.category" :items="categories"/></div><div class="filter-field"><label>{{labels[1]}}</label><VSelect v-model="f.entity" :items="[{value:'all',title:'全部'},...entities.map(e=>({value:e.id,title:e.name}))]"/></div><div v-if="subject==='nursing'" class="filter-field"><label>班次</label><VSelect v-model="f.shift" :items="[{value:'all',title:'全部班次'},{value:'day',title:'白班'},{value:'evening',title:'小夜班'},{value:'night',title:'大夜班'}]"/></div></template></div></VCard>
<VCard class="mb-6"><div class="toolbar"><VTextField v-model="f.search" placeholder="搜索指标名称" clearable class="toolbar-search"/><VSelect v-model="f.status" :items="[{value:'all',title:'全部状态'},...Object.entries(statuses).map(([value,title])=>({value,title}))]" style="max-width:210px"/><span>{{rows.length}} 项指标</span></div></VCard>
<div class="catalog-grid"><VCard v-for="m in rows" :key="m.id" class="definition-card" role="button" tabindex="0" @click="open(m)" @keydown.enter="open(m)" @keydown.space.prevent="open(m)"><VCardText><div class="card-kicker"><span>{{subjects.subjects[subject].name}} · 模拟数据</span><VChip :color="colors[m.status]" size="small" variant="tonal">{{statuses[m.status]}}</VChip></div><h2>{{m.name}}</h2><div class="metric-value">{{m.value??'—'}}<small>{{m.unit}}</small></div><p class="definition-desc">{{m.desc}}</p><div class="card-end"><span>{{f.start}} ~ {{f.end}}</span><span>历史趋势 ›</span></div></VCardText></VCard></div><VCard v-if="!rows.length" class="empty">当前范围没有匹配指标，请调整筛选。</VCard><p class="caption muted mt-5">{{subjects.subjects[subject].note}} · 全部数值为模拟数据，仅供演示。</p>
<VDialog v-model="detail" max-width="1050" scrollable><VCard v-if="selected" class="domain-dialog"><div class="dialog-heading"><h2>{{selected.name}} · 历史趋势</h2><VBtn icon="tabler-x" variant="text" aria-label="关闭趋势详情" @click="detail=false"/></div><VCardText><p class="caption muted">{{selected.reason}}</p><MetricTrend :dates="dates" :values="values" :unit="selected.unit" :title="drill==='all'?'当前筛选范围':all.find(e=>e.id===drill)?.name"/><div class="toolbar"><strong>{{subject==='hospital'?'全院范围':labels[1]+'明细'}}</strong><VBtn variant="text" @click="drill='all'">返回筛选范围</VBtn></div><VTable><thead><tr><th>统计对象</th><th>指标值</th><th>操作</th></tr></thead><tbody><tr v-for="r in breakdown.slice((page-1)*10,page*10)" :key="r.id"><td>{{r.name}}</td><td>{{r.value??'—'}} {{selected.unit}}</td><td><VBtn variant="text" @click="drill=r.id">查看趋势</VBtn></td></tr></tbody></VTable><div class="pagination-row"><span>共 {{breakdown.length}} 个主体</span><div><VBtn :disabled="page===1" variant="text" @click="page--">上一页</VBtn><VBtn :disabled="page*10>=breakdown.length" variant="text" @click="page++">下一页</VBtn></div></div></VCardText></VCard></VDialog></section></template>
